import test from 'node:test';import assert from 'node:assert/strict';
import {newGame,save,restore} from './simulation.js';import {surroundingPlaces} from './surroundings-data.js';import {surroundingsActions,performSurroundingsAction,surroundingsAtmosphere} from './surroundings.js';import {arrive} from './encounters.js';
test('all surroundings support observation, actual time, memory and saved facts without invented companions',()=>{for(const id of Object.keys(surroundingPlaces)){let s=arrive(newGame(),id).state;s.clock.minute=800;const names=Object.keys(s.contacts);s=performSurroundingsAction(s,'observe');assert.equal(s.clock.minute,810);assert.ok(s.known.includes(surroundingPlaces[id].fact));assert.deepEqual(Object.keys(s.contacts),names);const again=performSurroundingsAction(restore(save(s)),'observe');assert.equal(again.known.filter(x=>x===surroundingPlaces[id].fact).length,1);assert.notEqual(s.lastResult,again.lastResult);assert.ok(surroundingsAtmosphere(again));}});
test('late activities are unavailable and invalid actions do not mutate state',()=>{const s=newGame();s.location='footbridge';s.clock.minute=1311;assert.equal(surroundingsActions(s).length,0);const before=save(s);assert.throws(()=>performSurroundingsAction(s,'observe'));assert.equal(save(s),before);});
